INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-01', 'owner', 'audio-itops-a2-01', 'A2-B1 | 01. Morning Server Check & Handover (IT Ops)', 'Simple shift handover between two junior operators checking server status, alerts, and daily tickets (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-1', 'lesson-audio-itops-a2-01', 'owner', 0, 5.5, 'Good morning Ben, how was the night shift in the server room?', '[Ca sáng] Chào buổi sáng Ben, ca trực đêm ở phòng máy chủ thế nào?', 'night shift, server room', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-2', 'lesson-audio-itops-a2-01', 'owner', 5.5, 11, 'It was very quiet, and all main servers are running normally today.', '[Ca đêm] Rất yên tĩnh, và tất cả máy chủ chính hôm nay đều đang chạy bình thường.', 'quiet, running normally', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-3', 'lesson-audio-itops-a2-01', 'owner', 11, 16.5, 'Did we get any red alerts on the monitoring screen last night?', '[Ca sáng] Đêm qua màn hình giám sát có báo cảnh báo đỏ nào không?', 'alerts, monitoring screen', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-4', 'lesson-audio-itops-a2-01', 'owner', 16.5, 22.8, 'We had one yellow warning on mail server two around three in the morning.', '[Ca đêm] Ta có một cảnh báo vàng ở máy chủ thư số hai vào khoảng ba giờ sáng.', 'warning, mail server', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-5', 'lesson-audio-itops-a2-01', 'owner', 22.8, 28.3, 'What caused that warning, and did you need to restart the machine?', '[Ca sáng] Nguyên nhân cảnh báo là gì, cậu có cần khởi động lại máy không?', 'caused, restart', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-6', 'lesson-audio-itops-a2-01', 'owner', 28.3, 35, 'The memory was briefly high during a backup job, then it went back to normal.', '[Ca đêm] Bộ nhớ tăng cao một lúc khi chạy sao lưu, sau đó tự trở lại bình thường.', 'briefly, backup job, normal', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-7', 'lesson-audio-itops-a2-01', 'owner', 35, 40.5, 'Great, are there any open support tickets waiting for the morning team?', '[Ca sáng] Tốt quá, còn phiếu hỗ trợ nào đang mở chờ ca sáng xử lý không?', 'support tickets, waiting', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-8', 'lesson-audio-itops-a2-01', 'owner', 40.5, 46.8, 'Only two small printer requests, and I already wrote short notes in our logbook.', '[Ca đêm] Chỉ còn hai yêu cầu máy in nhỏ thôi, mình đã ghi chú ngắn vào sổ trực rồi.', 'requests, notes, logbook', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-01-seg-9', 'lesson-audio-itops-a2-01', 'owner', 46.8, 52.7, 'Thanks for the clear handover, Ben; go home and get some good rest.', '[Ca sáng] Cảm ơn bàn giao rõ ràng nhé Ben; về nhà nghỉ ngơi cho khỏe đi.', 'handover, rest', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-02', 'owner', 'audio-itops-a2-02', 'A2-B1 | 02. Locked Account & Password Reset Call (IT Support)', 'Everyday IT helpdesk phone call helping a staff member unlock an account and set a safe password (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-1', 'lesson-audio-itops-a2-02', 'owner', 0, 5, 'Hello, IT helpdesk speaking; how can I help you this morning?', '[Helpdesk] Xin chào, bộ phận hỗ trợ IT nghe ạ; sáng nay tôi có thể giúp gì cho bạn?', 'helpdesk, speaking', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-2', 'lesson-audio-itops-a2-02', 'owner', 5, 11.3, 'Hi, I cannot sign in to my work email because my account is locked.', '[Nhân viên] Chào bạn, tôi không đăng nhập được email công ty vì tài khoản bị khóa rồi.', 'sign in, locked', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-3', 'lesson-audio-itops-a2-02', 'owner', 11.3, 17.6, 'Do not worry, I can unlock it for you in just a few minutes.', '[Helpdesk] Đừng lo, tôi có thể mở khóa giúp bạn chỉ trong vài phút.', 'unlock, a few minutes', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-4', 'lesson-audio-itops-a2-02', 'owner', 17.6, 23.1, 'First, could you please tell me your full name and employee number?', '[Helpdesk] Trước tiên, bạn vui lòng cho tôi biết họ tên đầy đủ và mã nhân viên nhé?', 'full name, employee number', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-5', 'lesson-audio-itops-a2-02', 'owner', 23.1, 29.4, 'Sure, my name is Claire Evans, and my number is four zero eight two.', '[Nhân viên] Được ạ, tôi tên Claire Evans, mã nhân viên là 4082.', 'number', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-6', 'lesson-audio-itops-a2-02', 'owner', 29.4, 35.3, 'Thank you Claire; I see five wrong password attempts on your login screen.', '[Helpdesk] Cảm ơn Claire; tôi thấy có năm lần nhập sai mật khẩu trên màn hình đăng nhập của bạn.', 'wrong password, attempts, login screen', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-7', 'lesson-audio-itops-a2-02', 'owner', 35.3, 41.2, 'Yes, my keyboard had caps lock turned on, so I typed it wrong.', '[Nhân viên] Đúng rồi, bàn phím tôi đang bật phím viết hoa nên tôi gõ sai.', 'keyboard, caps lock, typed', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-8', 'lesson-audio-itops-a2-02', 'owner', 41.2, 47.1, 'I have unlocked your account and sent a temporary link to your phone.', '[Helpdesk] Tôi đã mở khóa tài khoản và gửi một đường dẫn tạm thời tới điện thoại của bạn.', 'temporary link', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-02-seg-9', 'lesson-audio-itops-a2-02', 'owner', 47.1, 53, 'Please choose a strong new password with letters and numbers, then try again.', '[Helpdesk] Bạn hãy chọn mật khẩu mới mạnh có cả chữ và số rồi thử đăng nhập lại nhé.', 'strong password, letters, numbers', 8);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-03', 'owner', 'audio-itops-a2-03', 'A2-B1 | 03. Slow Office WiFi & Router Restart (IT Support)', 'Practical workplace call diagnosing slow internet on the third floor, checking cables, and restarting the router (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-1', 'lesson-audio-itops-a2-03', 'owner', 0, 5.9, 'Hi Sam, the internet on the third floor is very slow this afternoon.', '[Nhân viên] Chào Sam, mạng internet ở tầng ba chiều nay rất chậm.', 'third floor, slow', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-2', 'lesson-audio-itops-a2-03', 'owner', 5.9, 12.2, 'Is it slow only on your laptop, or are your colleagues having trouble too?', '[IT Support] Chỉ chậm trên máy tính xách tay của bạn hay đồng nghiệp cũng gặp trục trặc?', 'laptop, colleagues, having trouble', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-3', 'lesson-audio-itops-a2-03', 'owner', 12.2, 18.1, 'Everyone near the meeting room keeps losing their video calls every few minutes.', '[Nhân viên] Mọi người gần phòng họp đều cứ bị rớt cuộc gọi video sau vài phút.', 'meeting room, losing, video calls', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-4', 'lesson-audio-itops-a2-03', 'owner', 18.1, 24.4, 'Let me check the network panel; the wireless router on your floor looks busy.', '[IT Support] Để tôi kiểm tra bảng điều khiển mạng; bộ phát WiFi ở tầng bạn có vẻ đang quá tải.', 'network panel, wireless router, busy', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-5', 'lesson-audio-itops-a2-03', 'owner', 24.4, 31.1, 'Could you look at the small white box on the wall and check the lights?', '[IT Support] Bạn có thể nhìn hộp trắng nhỏ trên tường và kiểm tra các đèn báo giúp tôi không?', 'box on the wall, lights', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-6', 'lesson-audio-itops-a2-03', 'owner', 31.1, 37.4, 'The power light is green, but the network light is blinking orange very fast.', '[Nhân viên] Đèn nguồn màu xanh lá, nhưng đèn mạng đang nhấp nháy màu cam rất nhanh.', 'power light, blinking orange', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-7', 'lesson-audio-itops-a2-03', 'owner', 37.4, 44.1, 'I will restart that access point remotely now, so WiFi will drop for one minute.', '[IT Support] Tôi sẽ khởi động lại điểm phát sóng đó từ xa ngay, nên WiFi sẽ ngắt khoảng một phút.', 'access point, remotely, drop', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-03-seg-8', 'lesson-audio-itops-a2-03', 'owner', 44.1, 50.4, 'The orange light turned solid green, and our pages are loading fast again now.', '[Nhân viên] Đèn cam chuyển sang xanh đứng yên rồi, các trang web cũng tải nhanh lại ngay.', 'solid green, loading fast', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-04', 'owner', 'audio-itops-a2-04', 'A2-B1 | 04. Daily Backup Check & Free Disk Space (IT Ops)', 'Simple operations chat about checking last night''s backup status and cleaning up old temporary files (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-1', 'lesson-audio-itops-a2-04', 'owner', 0, 5.9, 'Hey Anna, did the nightly backup finish safely on our main file server?', '[Ops] Chào Anna, bản sao lưu hằng đêm trên máy chủ tệp chính có hoàn tất an toàn không?', 'nightly backup, file server', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-2', 'lesson-audio-itops-a2-04', 'owner', 5.9, 12.2, 'Not completely; the backup stopped halfway because the storage drive ran out of space.', '[Junior Ops] Chưa hoàn toàn; bản sao lưu dừng giữa chừng vì ổ đĩa lưu trữ bị hết dung lượng.', 'stopped halfway, storage drive, ran out of space', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-3', 'lesson-audio-itops-a2-04', 'owner', 12.2, 18.5, 'Let us check which folder is taking up the most room on that drive.', '[Ops] Hãy kiểm tra xem thư mục nào đang chiếm nhiều chỗ nhất trên ổ đĩa đó.', 'folder, taking up, room', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-4', 'lesson-audio-itops-a2-04', 'owner', 18.5, 25.2, 'I see hundreds of old temporary files from last month still sitting inside the folder.', '[Junior Ops] Mình thấy hàng trăm tệp tạm cũ từ tháng trước vẫn còn nằm trong thư mục.', 'temporary files, sitting inside', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-5', 'lesson-audio-itops-a2-04', 'owner', 25.2, 31.1, 'Are any active users or programs still using those old files right now?', '[Ops] Có người dùng hay chương trình nào đang hoạt động còn dùng các tệp cũ đó không?', 'active users, programs', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-6', 'lesson-audio-itops-a2-04', 'owner', 31.1, 37.4, 'No, they are just finished export files that we only keep for seven days.', '[Junior Ops] Không, đó chỉ là các tệp xuất dữ liệu đã xong mà ta chỉ giữ lại bảy ngày.', 'export files, keep', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-7', 'lesson-audio-itops-a2-04', 'owner', 37.4, 43.7, 'Okay, delete the files older than two weeks and run the backup job again.', '[Ops] Được rồi, hãy xóa các tệp cũ hơn hai tuần rồi chạy lại tác vụ sao lưu nhé.', 'older than, backup job', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-04-seg-8', 'lesson-audio-itops-a2-04', 'owner', 43.7, 50.4, 'We now have forty percent free space, and the new backup finished with zero errors.', '[Junior Ops] Giờ ta đã có 40% dung lượng trống, và bản sao lưu mới vừa chạy xong không lỗi nào.', 'free space, zero errors', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-05', 'owner', 'audio-itops-a2-05', 'A2-B1 | 05. Website Down? Basic First Checks (IT Ops)', 'Clear beginner IT Ops conversation walking through the first steps when a customer reports the company website is down (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-1', 'lesson-audio-itops-a2-05', 'owner', 0, 5.9, 'Tom, a client just messaged us saying our company website will not open.', '[Support] Tom ơi, một khách hàng vừa nhắn tin báo trang web công ty không mở được.', 'messaged, website', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-2', 'lesson-audio-itops-a2-05', 'owner', 5.9, 12.6, 'Let me test the address from my browser and check our public status page first.', '[Ops] Để mình thử mở địa chỉ từ trình duyệt và kiểm tra trang trạng thái công khai trước.', 'browser, status page', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-3', 'lesson-audio-itops-a2-05', 'owner', 12.6, 18.9, 'I see an error page too, so the problem is definitely on our side.', '[Ops] Mình cũng thấy trang báo lỗi, vậy chắc chắn sự cố nằm ở phía hệ thống của mình.', 'error page, definitely, on our side', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-4', 'lesson-audio-itops-a2-05', 'owner', 18.9, 25.2, 'Should we tell the manager right away, or check the web service logs first?', '[Support] Ta nên báo quản lý ngay lập tức, hay kiểm tra nhật ký dịch vụ web trước?', 'right away, service logs', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-5', 'lesson-audio-itops-a2-05', 'owner', 25.2, 31.9, 'Always check the service status first so we can share useful facts in our update.', '[Ops] Luôn kiểm tra trạng thái dịch vụ trước để ta chia sẻ thông tin hữu ích khi cập nhật.', 'service status, useful facts', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-6', 'lesson-audio-itops-a2-05', 'owner', 31.9, 38.6, 'Look here, the web service stopped five minutes ago right after a small setting change.', '[Ops] Nhìn đây này, dịch vụ web đã dừng năm phút trước ngay sau một thay đổi cài đặt nhỏ.', 'setting change', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-7', 'lesson-audio-itops-a2-05', 'owner', 38.6, 44.9, 'I will undo that setting change and start the web service back up cleanly.', '[Ops] Mình sẽ hoàn tác thay đổi cài đặt đó và khởi động lại dịch vụ web thật gọn.', 'undo, start back up', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-05-seg-8', 'lesson-audio-itops-a2-05', 'owner', 44.9, 52, 'The homepage is online again, and I will reply to the client with a quick apology.', '[Support] Trang chủ lên mạng lại rồi, để mình nhắn trả lời xin lỗi nhanh cho khách hàng.', 'homepage, online, apology', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-a2-06', 'owner', 'audio-itops-a2-06', 'A2-B1 | 06. Planning a Weekend Software Update (IT Ops)', 'Clear A2-B1 workplace chat planning a Saturday night server update, notifying users, saving a backup, and running quick tests (~1 min, A2-B1, UK English).', 'en', 'Beginner');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-1', 'lesson-audio-itops-a2-06', 'owner', 0, 6.3, 'Hi Maya, when should we install the new security update on our office servers?', '[SysAdmin] Chào Maya, khi nào ta nên cài bản cập nhật bảo mật mới trên các máy chủ văn phòng?', 'install, security update', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-2', 'lesson-audio-itops-a2-06', 'owner', 6.3, 12.6, 'Saturday night at eleven is best because nobody is working in the office then.', '[Ops Lead] Tối thứ Bảy lúc mười một giờ là tốt nhất vì lúc đó không ai làm việc ở văn phòng.', 'nobody, working', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-3', 'lesson-audio-itops-a2-06', 'owner', 12.6, 18.5, 'How long will the systems be offline while the servers install and restart?', '[SysAdmin] Các hệ thống sẽ tạm ngưng bao lâu trong lúc máy chủ cài đặt và khởi động lại?', 'offline, restart', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-4', 'lesson-audio-itops-a2-06', 'owner', 18.5, 24.4, 'Usually around twenty minutes, though we should tell staff to expect thirty minutes.', '[Ops Lead] Thường khoảng hai mươi phút, nhưng ta nên báo nhân viên dự phòng ba mươi phút.', 'usually, expect', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-5', 'lesson-audio-itops-a2-06', 'owner', 24.4, 30.3, 'I will send a short reminder email to every department on Friday morning.', '[SysAdmin] Tôi sẽ gửi một email nhắc nhở ngắn cho mọi phòng ban vào sáng thứ Sáu.', 'reminder email, department', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-6', 'lesson-audio-itops-a2-06', 'owner', 30.3, 36.2, 'Please also make a fresh backup copy before you press the update button.', '[Ops Lead] Nhớ tạo thêm một bản sao lưu mới trước khi bạn bấm nút cập nhật nhé.', 'fresh backup copy, press', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-7', 'lesson-audio-itops-a2-06', 'owner', 36.2, 42.1, 'Of course, if anything breaks, we can restore the old version very quickly.', '[SysAdmin] Chắc chắn rồi, nếu có gì hỏng ta có thể khôi phục phiên bản cũ rất nhanh.', 'breaks, restore, old version', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-a2-06-seg-8', 'lesson-audio-itops-a2-06', 'owner', 42.1, 49.2, 'After the restart finishes, test login and email once, then post a green check in chat.', '[Ops Lead] Sau khi khởi động lại xong, hãy thử đăng nhập và email một lần rồi nhắn báo xanh vào nhóm chat nhé.', 'test login, post', 7);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-01', 'owner', 'audio-itops-b1-01', 'B1 | 01. Investigating High Memory Usage on Production (IT Ops)', 'A 2-minute B1 IT Operations call tracking steady memory growth on a production server, draining traffic safely, and recovering after a release (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-1', 'lesson-audio-itops-b1-01', 'owner', 0, 7.5, 'Hi Daniel, I am calling because memory usage on application server two just passed eighty five percent.', '[Monitoring] Chào Daniel, tôi gọi vì mức dùng bộ nhớ trên máy chủ ứng dụng số hai vừa vượt qua 85%.', 'memory usage, application server', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-2', 'lesson-audio-itops-b1-01', 'owner', 7.5, 14.6, 'Thanks for alerting me early; did the jump happen suddenly, or has it been rising slowly?', '[SysAdmin] Cảm ơn đã báo sớm; mức tăng đó xảy ra đột ngột hay đã tăng dần từ từ?', 'alerting, suddenly, rising slowly', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-3', 'lesson-audio-itops-b1-01', 'owner', 14.6, 20.9, 'Looking at the graph, memory started climbing steadily right after last night’s software update.', '[Monitoring] Nhìn vào biểu đồ, bộ nhớ bắt đầu tăng đều ngay sau bản cập nhật phần mềm tối qua.', 'graph, climbing steadily, software update', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-4', 'lesson-audio-itops-b1-01', 'owner', 20.9, 26.8, 'Are the other application servers showing the same upward pattern on the dashboard?', '[SysAdmin] Các máy chủ ứng dụng khác có hiển thị xu hướng tăng giống vậy trên bảng điều khiển không?', 'upward pattern, dashboard', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-5', 'lesson-audio-itops-b1-01', 'owner', 26.8, 33.5, 'Yes, server one is already at seventy eight percent, and server three is close behind.', '[Monitoring] Có, máy chủ số một đã ở mức 78%, còn máy chủ số ba cũng bám sát phía sau.', 'close behind', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-6', 'lesson-audio-itops-b1-01', 'owner', 33.5, 39.8, 'That strongly suggests the new release is not freeing memory after finishing background tasks.', '[SysAdmin] Điều đó cho thấy rõ bản phát hành mới không giải phóng bộ nhớ sau khi hoàn tất tác vụ nền.', 'strongly suggests, freeing memory, background tasks', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-7', 'lesson-audio-itops-b1-01', 'owner', 39.8, 46.1, 'Are customers experiencing slow page loads or error messages on the website right now?', '[SysAdmin] Khách hàng có đang gặp tình trạng tải trang chậm hay báo lỗi trên trang web lúc này không?', 'experiencing, page loads', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-8', 'lesson-audio-itops-b1-01', 'owner', 46.1, 53.2, 'Not yet, response times are still normal, though we might hit the limit within two hours.', '[Monitoring] Chưa ạ, thời gian phản hồi vẫn bình thường, nhưng có thể chạm giới hạn trong vòng hai giờ nữa.', 'response times, hit the limit', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-9', 'lesson-audio-itops-b1-01', 'owner', 53.2, 59.9, 'Let us act before users notice; first, remove server two from the active load balancer.', '[SysAdmin] Hãy xử lý trước khi người dùng nhận ra; trước hết hãy gỡ máy chủ số hai khỏi bộ cân bằng tải đang chạy.', 'act before, load balancer', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-10', 'lesson-audio-itops-b1-01', 'owner', 59.9, 66.2, 'Should I wait for current user sessions to finish before stopping the application process?', '[Monitoring] Tôi có nên chờ các phiên người dùng hiện tại kết thúc trước khi dừng tiến trình ứng dụng không?', 'user sessions, application process', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-11', 'lesson-audio-itops-b1-01', 'owner', 66.2, 72.9, 'Yes, give it thirty seconds to drain existing connections so nobody loses their shopping cart.', '[SysAdmin] Đúng rồi, chờ ba mươi giây để rút hết kết nối đang mở để không ai bị mất giỏ hàng.', 'drain, existing connections', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-12', 'lesson-audio-itops-b1-01', 'owner', 72.9, 80, 'Server two is drained now; do you want a quick memory report before I restart it?', '[Monitoring] Máy chủ số hai đã rút lưu lượng xong; anh có cần lấy báo cáo bộ nhớ nhanh trước khi tôi khởi động lại không?', 'memory report, restart', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-13', 'lesson-audio-itops-b1-01', 'owner', 80, 85.9, 'Please save the process summary and memory snapshot into our shared troubleshooting folder.', '[SysAdmin] Nhớ lưu bản tóm tắt tiến trình và bản chụp bộ nhớ vào thư mục xử lý sự cố dùng chung nhé.', 'process summary, troubleshooting folder', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-14', 'lesson-audio-itops-b1-01', 'owner', 85.9, 93, 'Both files are saved cleanly, and I am restarting the service on server two right now.', '[Monitoring] Cả hai tệp đã lưu gọn gàng, và tôi đang khởi động lại dịch vụ trên máy chủ số hai ngay đây.', 'saved cleanly', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-15', 'lesson-audio-itops-b1-01', 'owner', 93, 101, 'Once health checks pass, add server two back, then we will roll back to the previous stable version.', '[SysAdmin] Khi kiểm tra sức khỏe đạt, hãy đưa máy chủ số hai vào lại rồi ta sẽ hoàn tác về phiên bản ổn định trước đó.', 'health checks, roll back, stable version', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-16', 'lesson-audio-itops-b1-01', 'owner', 101, 109, 'Server two is healthy at thirty percent memory, and I am starting the rolling update on server one.', '[Monitoring] Máy chủ số hai đã ổn định ở mức 30% bộ nhớ, tôi đang bắt đầu cập nhật cuốn chiếu trên máy chủ số một.', 'rolling update', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-17', 'lesson-audio-itops-b1-01', 'owner', 109, 116.5, 'I will share the memory report with the development team so they can fix the leak today.', '[SysAdmin] Tôi sẽ gửi báo cáo bộ nhớ cho đội phát triển để họ sửa lỗi rò rỉ trong hôm nay.', 'development team, fix the leak', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-01-seg-18', 'lesson-audio-itops-b1-01', 'owner', 116.5, 124.5, 'All three servers are stable again, and I will keep watching the memory graph for the next hour.', '[Monitoring] Cả ba máy chủ đã ổn định trở lại, tôi sẽ tiếp tục theo dõi biểu đồ bộ nhớ trong một giờ tới.', 'keep watching, next hour', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-02', 'owner', 'audio-itops-b1-02', 'B1 | 02. Fixing a Broken VPN Tunnel for Branch Office (IT Ops)', 'A 2-minute B1 networking conversation resolving a disconnected site-to-site VPN tunnel, expired shared key, and routing checks (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-1', 'lesson-audio-itops-b1-02', 'owner', 0, 6.7, 'Hello Oliver, staff at our Manchester branch cannot open the internal finance system this morning.', '[Branch Support] Chào Oliver, nhân viên tại chi nhánh Manchester sáng nay không mở được hệ thống tài chính nội bộ.', 'branch, internal finance system', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-2', 'lesson-audio-itops-b1-02', 'owner', 6.7, 13.4, 'Can they still browse normal public websites, or is the whole office internet connection down?', '[Network Eng] Họ vẫn vào được các trang web công khai bình thường, hay cả đường truyền internet văn phòng bị mất?', 'browse, public websites, connection down', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-3', 'lesson-audio-itops-b1-02', 'owner', 13.4, 20.1, 'Public websites work fine, and office email loads quickly, so only internal tools are failing.', '[Branch Support] Các trang web công khai chạy tốt và email văn phòng tải nhanh, nên chỉ các công cụ nội bộ bị lỗi.', 'internal tools, failing', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-4', 'lesson-audio-itops-b1-02', 'owner', 20.1, 27.6, 'That sounds like a problem with the secure VPN tunnel between Manchester and our main data centre.', '[Network Eng] Nghe giống sự cố ở đường hầm VPN bảo mật giữa Manchester và trung tâm dữ liệu chính của ta.', 'VPN tunnel, data centre', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-5', 'lesson-audio-itops-b1-02', 'owner', 27.6, 34.3, 'Let me log into the central network gateway and check the tunnel status right away.', '[Network Eng] Để tôi đăng nhập vào cổng mạng trung tâm và kiểm tra trạng thái đường hầm ngay lập tức.', 'network gateway, tunnel status', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-6', 'lesson-audio-itops-b1-02', 'owner', 34.3, 41, 'Yes, the tunnel went offline at six thirty this morning and keeps failing to reconnect.', '[Network Eng] Đúng rồi, đường hầm đã ngắt kết nối lúc sáu giờ ba mươi sáng nay và cứ kết nối lại thất bại.', 'went offline, reconnect', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-7', 'lesson-audio-itops-b1-02', 'owner', 41, 47.7, 'Did someone change the branch firewall rules overnight, or did the internet provider drop packets?', '[Branch Support] Có ai đổi quy tắc tường lửa chi nhánh qua đêm không, hay nhà mạng bị rớt gói tin?', 'firewall rules, internet provider, drop packets', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-8', 'lesson-audio-itops-b1-02', 'owner', 47.7, 54, 'The gateway logs show an authentication error because the shared security key expired today.', '[Network Eng] Nhật ký cổng mạng báo lỗi xác thực vì khóa bảo mật dùng chung vừa hết hạn hôm nay.', 'authentication error, shared security key, expired', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-9', 'lesson-audio-itops-b1-02', 'owner', 54, 59.9, 'I did not realise those tunnel keys had a fixed yearly expiry date.', '[Branch Support] Tôi không để ý là các khóa đường hầm đó có ngày hết hạn cố định hằng năm.', 'realise, expiry date', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-10', 'lesson-audio-itops-b1-02', 'owner', 59.9, 67, 'We rotate them every twelve months for security, and the reminder ticket was missed last week.', '[Network Eng] Chúng tôi thay mới chúng mỗi mười hai tháng để bảo mật, và phiếu nhắc nhở tuần trước bị bỏ sót.', 'rotate, reminder ticket, missed', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-11', 'lesson-audio-itops-b1-02', 'owner', 67, 74.5, 'Can you update the key from headquarters, or do I need to plug into the local router?', '[Branch Support] Anh có thể cập nhật khóa từ trụ sở chính không, hay tôi cần cắm máy vào bộ định tuyến tại chỗ?', 'headquarters, local router', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-12', 'lesson-audio-itops-b1-02', 'owner', 74.5, 81.6, 'I can reach the branch router over our backup management line, so no cables are needed.', '[Network Eng] Tôi truy cập được bộ định tuyến chi nhánh qua đường quản trị dự phòng nên không cần cắm dây đâu.', 'backup management line, cables', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-13', 'lesson-audio-itops-b1-02', 'owner', 81.6, 88.3, 'I just generated a fresh key and applied the matching settings on both gateway devices.', '[Network Eng] Tôi vừa tạo một khóa mới và áp dụng cấu hình khớp nhau trên cả hai thiết bị cổng mạng.', 'generated, matching settings', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-14', 'lesson-audio-itops-b1-02', 'owner', 88.3, 95.4, 'Now I am resetting the tunnel interface; give it twenty seconds to negotiate the encrypted link.', '[Network Eng] Giờ tôi đang đặt lại giao diện đường hầm; chờ khoảng hai mươi giây để thương lượng liên kết mã hóa.', 'interface, negotiate, encrypted link', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-15', 'lesson-audio-itops-b1-02', 'owner', 95.4, 102.9, 'The status light just turned green on my dashboard, and test pings are returning in twelve milliseconds.', '[Network Eng] Đèn trạng thái vừa chuyển xanh trên bảng điều khiển của tôi, và lệnh ping thử phản hồi trong mười hai mili giây.', 'test pings, milliseconds', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-16', 'lesson-audio-itops-b1-02', 'owner', 102.9, 110, 'Let me ask the finance team to refresh their browsers and sign in again right now.', '[Branch Support] Để tôi nhờ nhóm tài chính tải lại trình duyệt và đăng nhập lại ngay lúc này.', 'refresh, sign in', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-17', 'lesson-audio-itops-b1-02', 'owner', 110, 116.7, 'They confirmed the invoices are loading smoothly, and the shared network drive is visible again.', '[Branch Support] Họ xác nhận hóa đơn tải mượt rồi, ổ đĩa mạng dùng chung cũng hiện lại bình thường.', 'confirmed, shared network drive', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-02-seg-18', 'lesson-audio-itops-b1-02', 'owner', 116.7, 123.4, 'Brilliant; I will schedule an automatic calendar alert thirty days before next year’s key renewal.', '[Network Eng] Tuyệt vời; tôi sẽ đặt cảnh báo lịch tự động trước ba mươi ngày cho kỳ gia hạn khóa năm tới.', 'schedule, calendar alert, renewal', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-03', 'owner', 'audio-itops-b1-03', 'B1 | 03. Handling a Sudden Traffic Spike During Sales (IT Ops)', 'A 2-minute B1 cloud operations call managing a flash-sale traffic surge with extra web instances, caching, and checkout monitoring (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-1', 'lesson-audio-itops-b1-03', 'owner', 0, 7.1, 'Hey Grace, our marketing team just sent out a flash sale email and website traffic doubled.', '[Ops Lead] Chào Grace, đội marketing vừa gửi email khuyến mãi chớp nhoáng và lưu lượng web tăng gấp đôi rồi.', 'flash sale, traffic doubled', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-2', 'lesson-audio-itops-b1-03', 'owner', 7.1, 15.1, 'I saw the live chart jump a minute ago; how are the web servers coping with the load?', '[Cloud Eng] Tôi thấy biểu đồ trực tiếp nhảy vọt một phút trước; các máy chủ web đang chịu tải thế nào?', 'live chart, coping with the load', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-3', 'lesson-audio-itops-b1-03', 'owner', 15.1, 22.2, 'Average CPU across the web cluster is around seventy five percent, and page loads feel slower.', '[Ops Lead] CPU trung bình trên cụm web khoảng 75%, và trang web bắt đầu tải chậm hơn.', 'web cluster, page loads', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-4', 'lesson-audio-itops-b1-03', 'owner', 22.2, 28.1, 'Did automatic scaling start launching extra server instances when CPU crossed seventy percent?', '[Cloud Eng] Hệ thống tự động mở rộng đã bắt đầu khởi chạy thêm máy chủ khi CPU vượt 70% chưa?', 'automatic scaling, launching, instances', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-5', 'lesson-audio-itops-b1-03', 'owner', 28.1, 35.6, 'It added two instances, but the maximum limit was set to six servers in our scaling policy.', '[Ops Lead] Nó đã thêm hai máy chủ, nhưng giới hạn tối đa trong chính sách mở rộng chỉ đặt là sáu máy.', 'maximum limit, scaling policy', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-6', 'lesson-audio-itops-b1-03', 'owner', 35.6, 43.1, 'Let us raise that ceiling to ten instances right now so the cluster has comfortable breathing room.', '[Cloud Eng] Hãy nâng trần giới hạn lên mười máy chủ ngay để cụm có khoảng trống an toàn.', 'raise that ceiling, breathing room', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-7', 'lesson-audio-itops-b1-03', 'owner', 43.1, 50.2, 'How long does each new web server take to boot up and pass its health check?', '[Ops Lead] Mỗi máy chủ web mới mất bao lâu để khởi động và vượt qua bài kiểm tra sức khỏe?', 'boot up, health check', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-8', 'lesson-audio-itops-b1-03', 'owner', 50.2, 56.9, 'About ninety seconds; two more servers are already starting and should join the balancer soon.', '[Cloud Eng] Khoảng chín mươi giây; hai máy chủ nữa đã bắt đầu chạy và sẽ sớm tham gia bộ cân bằng tải.', 'ninety seconds, join the balancer', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-9', 'lesson-audio-itops-b1-03', 'owner', 56.9, 63.6, 'What about the main database? Are heavy product searches putting too much pressure on it?', '[Ops Lead] Còn cơ sở dữ liệu chính thì sao? Lượt tìm kiếm sản phẩm nhiều có gây áp lực lớn lên nó không?', 'product searches, pressure', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-10', 'lesson-audio-itops-b1-03', 'owner', 63.6, 70.3, 'Database reads increased sharply, so enabling longer page caching for product lists will help immediately.', '[Cloud Eng] Lượt đọc database tăng mạnh, nên bật lưu đệm trang lâu hơn cho danh sách sản phẩm sẽ giúp ngay lập tức.', 'increased sharply, page caching', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-11', 'lesson-audio-itops-b1-03', 'owner', 70.3, 77, 'Make sure we do not cache personal cart pages or payment checkout screens by mistake.', '[Ops Lead] Nhớ đảm bảo ta không vô tình lưu đệm trang giỏ hàng cá nhân hay màn hình thanh toán nhé.', 'by mistake, checkout screens', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-12', 'lesson-audio-itops-b1-03', 'owner', 77, 83.3, 'Of course, caching only applies to public catalogue pages, images, and static banner files.', '[Cloud Eng] Chắc chắn rồi, bộ nhớ đệm chỉ áp dụng cho trang danh mục công khai, hình ảnh và tệp banner tĩnh.', 'catalogue pages, static files', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-13', 'lesson-audio-itops-b1-03', 'owner', 83.3, 90.4, 'The new cache rule is live, and database read traffic just dropped by nearly forty percent.', '[Cloud Eng] Quy tắc bộ nhớ đệm mới đã chạy, lưu lượng đọc cơ sở dữ liệu vừa giảm gần 40%.', 'cache rule, dropped by nearly', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-14', 'lesson-audio-itops-b1-03', 'owner', 90.4, 97.5, 'Awesome, and all eight web instances are now green with average CPU back under fifty percent.', '[Ops Lead] Tuyệt vời, cả tám máy chủ web đều đã xanh với mức CPU trung bình quay về dưới 50%.', 'average CPU, under fifty percent', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-15', 'lesson-audio-itops-b1-03', 'owner', 97.5, 105.5, 'I also ran a quick test order on the checkout page and it completed in under one second.', '[Cloud Eng] Tôi cũng vừa chạy một đơn hàng thử trên trang thanh toán và hoàn tất trong chưa đầy một giây.', 'test order, completed', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-16', 'lesson-audio-itops-b1-03', 'owner', 105.5, 111.8, 'Let us ask marketing to notify operations one day ahead before future flash sales.', '[Ops Lead] Hãy nhờ đội marketing báo trước cho bộ phận vận hành một ngày trước các đợt khuyến mãi sau.', 'notify, one day ahead', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-17', 'lesson-audio-itops-b1-03', 'owner', 111.8, 118.5, 'Good idea; that way we can pre warm the servers and review limits calmly beforehand.', '[Cloud Eng] Ý hay đấy; như vậy ta có thể làm nóng máy chủ trước và rà soát giới hạn thật bình tĩnh.', 'pre warm, calmly beforehand', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-03-seg-18', 'lesson-audio-itops-b1-03', 'owner', 118.5, 125.6, 'I will stay on the live dashboard until the sale ends and scale back down tonight.', '[Cloud Eng] Tôi sẽ theo dõi bảng điều khiển trực tiếp đến khi hết khuyến mãi rồi thu hẹp lại tối nay.', 'scale back down', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-04', 'owner', 'audio-itops-b1-04', 'B1 | 04. Resolving Email Delivery Delays & Queue Backlog (IT Ops)', 'A 2-minute B1 mail operations call diagnosing delayed customer invoices, inspecting a stuck mail queue, pausing a noisy loop, and flushing deliveries (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-1', 'lesson-audio-itops-b1-04', 'owner', 0, 6.7, 'Hi Hannah, several customers called support because their order confirmation emails still have not arrived.', '[Helpdesk] Chào Hannah, vài khách hàng gọi hỗ trợ vì email xác nhận đơn hàng vẫn chưa tới nơi.', 'order confirmation, arrived', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-2', 'lesson-audio-itops-b1-04', 'owner', 6.7, 13.8, 'Are those emails bouncing back with errors, or are they simply arriving much later than usual?', '[Mail Admin] Những email đó bị trả ngược báo lỗi hay chỉ đến chậm hơn bình thường nhiều?', 'bouncing back, later than usual', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-3', 'lesson-audio-itops-b1-04', 'owner', 13.8, 20.5, 'They are arriving about forty minutes late, and staff noticed internal notifications are delayed too.', '[Helpdesk] Chúng đến trễ khoảng bốn mươi phút, và nhân viên cũng thấy thông báo nội bộ bị chậm theo.', 'delayed, internal notifications', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-4', 'lesson-audio-itops-b1-04', 'owner', 20.5, 28.5, 'Let me check our outgoing mail relay server; wow, there are twelve thousand messages stuck in the queue.', '[Mail Admin] Để tôi kiểm tra máy chủ chuyển tiếp thư đi; ôi, có mười hai nghìn thư đang bị kẹt trong hàng đợi.', 'mail relay server, stuck in the queue', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-5', 'lesson-audio-itops-b1-04', 'owner', 28.5, 34.4, 'Twelve thousand? Normally our busy morning queue only holds around two hundred emails.', '[Helpdesk] Mười hai nghìn cơ à? Bình thường hàng đợi giờ cao điểm buổi sáng chỉ khoảng hai trăm email thôi.', 'normally, holds around', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-6', 'lesson-audio-itops-b1-04', 'owner', 34.4, 41.1, 'Wait a second, most of these messages are coming from one single automated reporting account.', '[Mail Admin] Khoan đã, phần lớn các thư này đều xuất phát từ duy nhất một tài khoản báo cáo tự động.', 'automated reporting account', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-7', 'lesson-audio-itops-b1-04', 'owner', 41.1, 48.2, 'What is that account sending? It looks like the same five megabyte attachment repeated every second.', '[Mail Admin] Tài khoản đó đang gửi gì vậy? Trông như cùng một tệp đính kèm năm megabyte lặp lại mỗi giây.', 'attachment, repeated', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-8', 'lesson-audio-itops-b1-04', 'owner', 48.2, 55.3, 'Oh no, a scheduled billing script must be stuck in a retry loop after failing once.', '[Helpdesk] Ôi không, chắc một kịch bản xuất hóa đơn định kỳ bị kẹt vòng lặp gửi lại sau khi lỗi một lần.', 'scheduled script, retry loop', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-9', 'lesson-audio-itops-b1-04', 'owner', 55.3, 61.6, 'Exactly; it filled up all outgoing worker slots, blocking real customer confirmations behind it.', '[Mail Admin] Chính xác; nó chiếm kín toàn bộ luồng gửi thư, chặn hết email xác nhận của khách hàng ở phía sau.', 'worker slots, blocking', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-10', 'lesson-audio-itops-b1-04', 'owner', 61.6, 68.7, 'First, I am pausing that automated sender account so no new duplicate messages enter the queue.', '[Mail Admin] Trước hết tôi tạm khóa tài khoản gửi tự động đó để không có thêm thư trùng lặp vào hàng đợi.', 'pausing, duplicate messages', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-11', 'lesson-audio-itops-b1-04', 'owner', 68.7, 75, 'Can we clear out only those duplicate report messages without deleting real customer emails?', '[Helpdesk] Mình có thể dọn riêng các thư báo cáo trùng lặp đó mà không xóa nhầm email khách hàng thật không?', 'clear out, without deleting', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-12', 'lesson-audio-itops-b1-04', 'owner', 75, 82.1, 'Yes, I can filter the queue by sender address and remove only the stuck reporting job.', '[Mail Admin] Được chứ, tôi có thể lọc hàng đợi theo địa chỉ người gửi và chỉ gỡ tác vụ báo cáo bị kẹt.', 'filter the queue, sender address', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-13', 'lesson-audio-itops-b1-04', 'owner', 82.1, 88.4, 'Done, eleven thousand duplicate messages are cleared, leaving only three hundred genuine customer emails.', '[Mail Admin] Xong rồi, mười một nghìn thư trùng đã được dọn, chỉ còn ba trăm email khách hàng thật.', 'genuine customer emails', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-14', 'lesson-audio-itops-b1-04', 'owner', 88.4, 95.5, 'Now I am flushing the mail queue so the relay server delivers those waiting confirmations immediately.', '[Mail Admin] Giờ tôi đẩy xả hàng đợi thư để máy chủ chuyển tiếp gửi ngay những thư xác nhận đang chờ.', 'flushing the mail queue, delivers', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-15', 'lesson-audio-itops-b1-04', 'owner', 95.5, 102.6, 'I just tested a password reset email and it landed in my inbox within three seconds.', '[Helpdesk] Tôi vừa thử một email đặt lại mật khẩu và nó vào hộp thư đến trong vòng ba giây.', 'landed in my inbox', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-16', 'lesson-audio-itops-b1-04', 'owner', 102.6, 110.6, 'Great news; I will also tell the billing team to add a strict retry limit on their script.', '[Mail Admin] Tin tốt quá; tôi cũng sẽ báo nhóm thanh toán thêm giới hạn thử lại chặt chẽ vào kịch bản của họ.', 'strict retry limit', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-17', 'lesson-audio-itops-b1-04', 'owner', 110.6, 118.6, 'Should we set a queue size alert so operations gets notified if more than five hundred emails wait?', '[Helpdesk] Ta có nên đặt cảnh báo kích thước hàng đợi để vận hành nhận tin khi có hơn năm trăm thư chờ không?', 'queue size alert, notified', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-04-seg-18', 'lesson-audio-itops-b1-04', 'owner', 118.6, 125.7, 'Yes, I am adding that monitoring rule right now along with a per minute sending limit.', '[Mail Admin] Có chứ, tôi đang thêm quy tắc giám sát đó ngay cùng với giới hạn số thư gửi mỗi phút.', 'monitoring rule, sending limit', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-05', 'owner', 'audio-itops-b1-05', 'B1 | 05. Cleaning Up Inodes & Stuck Background Jobs (IT Ops)', 'A 2-minute B1 Linux operations conversation solving a tricky "no space left" error caused by 100% inode usage from tiny session files (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-1', 'lesson-audio-itops-b1-05', 'owner', 0, 8.4, 'Hi Lucas, I am confused because the web server says no space left, even though disk space looks fine.', '[Junior Ops] Chào Lucas, mình hơi rối vì máy chủ web báo hết dung lượng dù dung lượng ổ đĩa trông vẫn ổn.', 'confused, no space left', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-2', 'lesson-audio-itops-b1-05', 'owner', 8.4, 14.7, 'How much free space did the standard disk command report when you checked it?', '[Linux Eng] Lệnh kiểm tra đĩa thông thường báo còn bao nhiêu dung lượng trống khi cậu xem?', 'disk command, report', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-3', 'lesson-audio-itops-b1-05', 'owner', 14.7, 22.2, 'It showed thirty five percent free, about forty gigabytes available, yet nothing can create a new file.', '[Junior Ops] Nó hiện còn 35% trống, khoảng bốn mươi gigabyte sẵn dùng, vậy mà không gì tạo được tệp mới.', 'available, create a new file', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-4', 'lesson-audio-itops-b1-05', 'owner', 22.2, 28.9, 'Aha, that is a classic Linux surprise; please check the inode usage table right now.', '[Linux Eng] À ha, đó là một tình huống Linux kinh điển; cậu kiểm tra ngay bảng mức dùng inode đi.', 'classic surprise, inode usage', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-5', 'lesson-audio-itops-b1-05', 'owner', 28.9, 35.2, 'Oh wow, inode usage on the root drive is sitting at one hundred percent.', '[Junior Ops] Ồ chà, mức sử dụng inode trên ổ đĩa gốc đang chạm đúng 100%.', 'root drive, sitting at', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-6', 'lesson-audio-itops-b1-05', 'owner', 35.2, 42.3, 'Could you quickly explain why a drive runs out of inodes while gigabytes are still free?', '[Junior Ops] Anh giải thích nhanh giúp vì sao ổ đĩa hết inode trong khi vẫn còn thừa hàng chục gigabyte được không?', 'quickly explain, runs out of', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-7', 'lesson-audio-itops-b1-05', 'owner', 42.3, 49.8, 'Every single file needs one inode record, so millions of tiny files can use up every slot.', '[Linux Eng] Mỗi tệp đều cần một bản ghi inode, nên hàng triệu tệp nhỏ xíu có thể chiếm sạch mọi vị trí.', 'inode record, tiny files, use up', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-8', 'lesson-audio-itops-b1-05', 'owner', 49.8, 56.5, 'Let us find which directory holds the highest number of small files on this machine.', '[Linux Eng] Hãy tìm xem thư mục nào đang chứa số lượng tệp nhỏ nhiều nhất trên máy này.', 'directory, highest number', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-9', 'lesson-audio-itops-b1-05', 'owner', 56.5, 63.6, 'Found it; the temporary session folder has over two million tiny files created over three months.', '[Junior Ops] Tìm thấy rồi; thư mục phiên tạm có hơn hai triệu tệp nhỏ được tạo suốt ba tháng qua.', 'session folder, two million', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-10', 'lesson-audio-itops-b1-05', 'owner', 63.6, 69.9, 'Why did our nightly cleanup job stop clearing old session files three months ago?', '[Linux Eng] Tại sao tác vụ dọn dẹp hằng đêm lại ngừng xóa các tệp phiên cũ từ ba tháng trước?', 'nightly cleanup job', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-11', 'lesson-audio-itops-b1-05', 'owner', 69.9, 77.4, 'Let me inspect the scheduled task file; someone commented out the cleanup line during testing and forgot.', '[Junior Ops] Để mình kiểm tra tệp tác vụ định kỳ; có ai đó đã vô hiệu dòng dọn dẹp lúc thử nghiệm rồi quên bật lại.', 'inspect, commented out, forgot', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-12', 'lesson-audio-itops-b1-05', 'owner', 77.4, 84.5, 'Good catch; remember not to run a plain delete wildcard on two million files at once.', '[Linux Eng] Phát hiện tốt đấy; nhớ đừng chạy lệnh xóa ký tự đại diện thông thường trên hai triệu tệp cùng lúc nhé.', 'good catch, wildcard, at once', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-13', 'lesson-audio-itops-b1-05', 'owner', 84.5, 90.8, 'Right, because the shell command will fail with an argument list too long error.', '[Junior Ops] Đúng rồi, vì lệnh shell sẽ báo lỗi danh sách tham số quá dài.', 'shell command, argument list', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-14', 'lesson-audio-itops-b1-05', 'owner', 90.8, 99.2, 'Use the find command with delete in batches for files older than two days so active sessions stay safe.', '[Linux Eng] Hãy dùng lệnh find kèm xóa theo lô cho tệp cũ hơn hai ngày để các phiên đang chạy vẫn an toàn.', 'in batches, older than, stay safe', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-15', 'lesson-audio-itops-b1-05', 'owner', 99.2, 106.7, 'It is running smoothly now, and inode usage already dropped from one hundred down to twenty percent.', '[Junior Ops] Lệnh đang chạy mượt rồi, mức dùng inode vừa giảm từ 100% xuống còn 20%.', 'running smoothly, dropped', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-16', 'lesson-audio-itops-b1-05', 'owner', 106.7, 113.8, 'Next, re enable the nightly cleanup schedule and verify that the web application writes logs cleanly.', '[Linux Eng] Tiếp theo hãy bật lại lịch dọn dẹp hằng đêm và kiểm tra xem ứng dụng web ghi log ổn chưa.', 're enable, verify', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-17', 'lesson-audio-itops-b1-05', 'owner', 113.8, 121.8, 'Application logs are writing again, and I added an inode alert at eighty percent to our monitoring tool.', '[Junior Ops] Log ứng dụng đã ghi trở lại, và mình đã thêm cảnh báo inode ở mức 80% vào công cụ giám sát.', 'inode alert, monitoring tool', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-05-seg-18', 'lesson-audio-itops-b1-05', 'owner', 121.8, 128.5, 'Nice work today; checking inodes is a great troubleshooting habit every Linux engineer should know.', '[Linux Eng] Hôm nay làm tốt lắm; kiểm tra inode là thói quen xử lý sự cố rất hay mà kỹ sư Linux nào cũng nên biết.', 'troubleshooting habit', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-06', 'owner', 'audio-itops-b1-06', 'B1 | 06. Planning a Safe Database Migration Weekend (IT Ops)', 'A 2-minute B1 planning conversation preparing a customer database migration to a larger server with staging rehearsals, verification, and rollback readiness (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-1', 'lesson-audio-itops-b1-06', 'owner', 0, 5.9, 'Good afternoon Priya, let us finalise our checklist for Saturday’s customer database migration.', '[Project Lead] Chào buổi chiều Priya, cùng chốt danh sách kiểm tra cho đợt chuyển đổi cơ sở dữ liệu khách hàng thứ Bảy này nhé.', 'finalise, checklist, database migration', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-2', 'lesson-audio-itops-b1-06', 'owner', 5.9, 13.4, 'Sure, our current server is running close to capacity, so moving to the new machine is essential.', '[DBA] Chắc chắn rồi, máy chủ hiện tại đã chạy gần kịch ngưỡng nên chuyển sang máy mới là rất cần thiết.', 'close to capacity, essential', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-3', 'lesson-audio-itops-b1-06', 'owner', 13.4, 19.7, 'How much total downtime should we communicate to customers for the Saturday night window?', '[Project Lead] Chúng ta nên thông báo tổng thời gian tạm ngưng là bao lâu cho khung giờ tối thứ Bảy?', 'communicate, downtime', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-4', 'lesson-audio-itops-b1-06', 'owner', 19.7, 26.8, 'In our staging rehearsal yesterday, the final switchover took twenty five minutes from start to finish.', '[DBA] Trong buổi diễn tập trên staging hôm qua, bước chuyển đổi cuối cùng mất hai mươi lăm phút từ đầu đến cuối.', 'staging rehearsal, switchover', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-5', 'lesson-audio-itops-b1-06', 'owner', 26.8, 33.5, 'Let us announce a one hour maintenance window so we have plenty of safety margin.', '[Project Lead] Hãy thông báo khung bảo trì một tiếng để ta có đủ biên độ an toàn.', 'announce, safety margin', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-6', 'lesson-audio-itops-b1-06', 'owner', 33.5, 40.2, 'How are we copying such a large database without keeping the website offline for hours?', '[Project Lead] Ta sao chép cơ sở dữ liệu lớn như vậy bằng cách nào mà không để trang web ngừng hoạt động hàng giờ?', 'copying, offline for hours', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-7', 'lesson-audio-itops-b1-06', 'owner', 40.2, 47.3, 'We already set up live replication, so the new server receives every change in real time.', '[DBA] Tụi mình đã thiết lập nhân bản trực tiếp rồi, nên máy chủ mới nhận mọi thay đổi theo thời gian thực.', 'live replication, real time', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-8', 'lesson-audio-itops-b1-06', 'owner', 47.3, 55.7, 'That means during maintenance we only pause writes briefly and wait for the last few rows to catch up.', '[DBA] Nghĩa là lúc bảo trì ta chỉ tạm dừng ghi dữ liệu một lát rồi chờ vài dòng cuối đồng bộ kịp.', 'pause writes, catch up', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-9', 'lesson-audio-itops-b1-06', 'owner', 55.7, 62.8, 'Once the data matches completely, how will we verify that nothing was missed during the transfer?', '[Project Lead] Khi dữ liệu khớp hoàn toàn, ta sẽ kiểm chứng thế nào để chắc không sót gì trong quá trình chuyển?', 'matches completely, transfer', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-10', 'lesson-audio-itops-b1-06', 'owner', 62.8, 69.9, 'I wrote a verification script that compares table row counts and checksums across all key tables.', '[DBA] Tôi đã viết một kịch bản kiểm chứng so sánh số dòng và mã kiểm tra trên mọi bảng chính.', 'verification script, row counts, checksums', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-11', 'lesson-audio-itops-b1-06', 'owner', 69.9, 77.4, 'And what happens if our application servers show unexpected errors right after pointing to the new database?', '[Project Lead] Còn chuyện gì xảy ra nếu các máy chủ ứng dụng báo lỗi bất ngờ ngay sau khi trỏ sang database mới?', 'unexpected errors, pointing to', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-12', 'lesson-audio-itops-b1-06', 'owner', 77.4, 84.5, 'We will keep the old database server untouched and online in read only mode all weekend.', '[DBA] Ta sẽ giữ nguyên máy chủ database cũ không đụng chạm và chạy ở chế độ chỉ đọc suốt cuối tuần.', 'untouched, read only mode', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-13', 'lesson-audio-itops-b1-06', 'owner', 84.5, 92.5, 'If any critical smoke test fails within fifteen minutes, we simply point traffic back to the old server.', '[DBA] Nếu bất kỳ bài kiểm thử nhanh quan trọng nào lỗi trong mười lăm phút, ta chỉ việc trỏ lưu lượng về lại máy cũ.', 'smoke test, point traffic back', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-14', 'lesson-audio-itops-b1-06', 'owner', 92.5, 100, 'Have we checked firewall rules and connection passwords so every app server can reach the new host?', '[Project Lead] Ta đã kiểm tra quy tắc tường lửa và mật khẩu kết nối để mọi máy chủ ứng dụng nối được tới máy mới chưa?', 'connection passwords, reach the new host', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-15', 'lesson-audio-itops-b1-06', 'owner', 100, 106.3, 'Yes, we tested network connectivity and login permissions from every production node earlier today.', '[DBA] Rồi ạ, đầu ngày hôm nay ta đã thử kết nối mạng và quyền đăng nhập từ từng máy chủ production.', 'network connectivity, login permissions', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-16', 'lesson-audio-itops-b1-06', 'owner', 106.3, 112.6, 'Also remember to take a fresh full backup snapshot right before pausing production writes.', '[Project Lead] Cũng nhớ chụp một bản sao lưu đầy đủ mới ngay trước khi tạm dừng ghi trên production nhé.', 'full backup snapshot', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-17', 'lesson-audio-itops-b1-06', 'owner', 112.6, 119.7, 'It is step two on our runbook, and two engineers will double check every command together.', '[DBA] Đó là bước hai trong sổ tay rồi, và hai kỹ sư sẽ cùng kiểm tra chéo từng câu lệnh.', 'runbook, double check', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-06-seg-18', 'lesson-audio-itops-b1-06', 'owner', 119.7, 127.2, 'Everything looks well prepared; let us meet on the bridge call at ten forty five Saturday night.', '[Project Lead] Mọi thứ chuẩn bị rất chu đáo rồi; hẹn gặp nhau trên cuộc gọi trực chiến lúc mười giờ bốn lăm tối thứ Bảy nhé.', 'well prepared, bridge call', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-07', 'owner', 'audio-itops-b1-07', 'B1 | 07. Responding to a Phishing Email & Account Check (IT Ops)', 'A 2-minute B1 security operations phone call helping an employee who clicked a fake invoice link, revoking sessions, blocking the domain, and enabling two-factor login (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-1', 'lesson-audio-itops-b1-07', 'owner', 0, 8.4, 'Hello security desk, I think I just made a mistake and clicked a suspicious invoice link in my email.', '[Staff] Xin chào bộ phận bảo mật, tôi nghĩ mình vừa lỡ tay bấm vào một đường dẫn hóa đơn đáng ngờ trong email.', 'made a mistake, suspicious invoice link', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-2', 'lesson-audio-itops-b1-07', 'owner', 8.4, 15.5, 'Thank you for calling immediately; reporting it fast is the best thing you could possibly do.', '[Security Ops] Cảm ơn bạn đã gọi ngay lập tức; báo sớm là điều tốt nhất bạn có thể làm lúc này.', 'reporting it fast', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-3', 'lesson-audio-itops-b1-07', 'owner', 15.5, 23.5, 'Tell me calmly what happened after you clicked the link; did a login page ask for your password?', '[Security Ops] Hãy kể bình tĩnh chuyện gì xảy ra sau khi bạn bấm link; có trang đăng nhập nào đòi mật khẩu không?', 'calmly, login page', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-4', 'lesson-audio-itops-b1-07', 'owner', 23.5, 32.7, 'Yes, it looked exactly like our company portal, so I typed my work email and password before noticing the strange address.', '[Staff] Có, nó giống hệt cổng nội bộ công ty nên tôi đã nhập email và mật khẩu trước khi nhận ra địa chỉ lạ.', 'company portal, strange address', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-5', 'lesson-audio-itops-b1-07', 'owner', 32.7, 39.8, 'Okay, do not panic; let me check your account login history and active sessions right now.', '[Security Ops] Được rồi, đừng hoảng; để tôi kiểm tra lịch sử đăng nhập và các phiên đang mở của bạn ngay đây.', 'do not panic, login history, active sessions', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-6', 'lesson-audio-itops-b1-07', 'owner', 39.8, 48.6, 'I see a login attempt from an unfamiliar city two minutes ago, so we need to lock it down fast.', '[Security Ops] Tôi thấy một lượt đăng nhập từ một thành phố lạ hai phút trước, nên ta cần khóa chặt ngay.', 'unfamiliar city, lock it down', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-7', 'lesson-audio-itops-b1-07', 'owner', 48.6, 55.7, 'First, I am signing out all active sessions across every device and temporarily resetting your password.', '[Security Ops] Trước tiên, tôi đăng xuất toàn bộ phiên đang hoạt động trên mọi thiết bị và đặt lại mật khẩu tạm thời.', 'signing out, active sessions', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-8', 'lesson-audio-itops-b1-07', 'owner', 55.7, 62.4, 'Did the attacker manage to open any shared files or forward emails from my mailbox?', '[Staff] Kẻ tấn công có kịp mở tệp dùng chung nào hay chuyển tiếp email từ hộp thư của tôi không?', 'attacker, forward emails, mailbox', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-9', 'lesson-audio-itops-b1-07', 'owner', 62.4, 69.5, 'Good news, the audit log shows zero file downloads and no hidden forwarding rules were added.', '[Security Ops] Tin tốt là nhật ký kiểm toán không ghi nhận lượt tải tệp nào và cũng chưa có quy tắc chuyển tiếp ẩn.', 'audit log, forwarding rules', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-10', 'lesson-audio-itops-b1-07', 'owner', 69.5, 75.4, 'What a relief; did the website download any strange attachment onto my laptop?', '[Staff] Thật nhẹ nhõm; trang web đó có tải tệp đính kèm lạ nào xuống máy tính xách tay của tôi không?', 'relief, attachment', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-11', 'lesson-audio-itops-b1-07', 'owner', 75.4, 82.9, 'Our endpoint protection scan shows your laptop is clean, though I will trigger a full quick check.', '[Security Ops] Công cụ bảo vệ thiết bị đầu cuối báo máy bạn sạch, nhưng tôi vẫn sẽ chạy thêm một lượt quét nhanh.', 'endpoint protection, scan', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-12', 'lesson-audio-itops-b1-07', 'owner', 82.9, 90.9, 'Please forward the phishing message to our security inbox so we can block that fake domain company wide.', '[Security Ops] Bạn hãy chuyển tiếp thư lừa đảo đó tới hộp thư bảo mật để ta chặn tên miền giả trên toàn công ty.', 'phishing message, fake domain, company wide', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-13', 'lesson-audio-itops-b1-07', 'owner', 90.9, 98.9, 'I am forwarding it now; do I also need to change my password on any other work apps?', '[Staff] Tôi đang chuyển tiếp đây; tôi có cần đổi mật khẩu trên ứng dụng công việc nào khác không?', 'change my password', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-14', 'lesson-audio-itops-b1-07', 'owner', 98.9, 106, 'Only if you reused the same password anywhere else; always keep your work password completely unique.', '[Security Ops] Chỉ khi bạn dùng lại đúng mật khẩu đó ở nơi khác; hãy luôn giữ mật khẩu công việc hoàn toàn riêng biệt.', 'reused, completely unique', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-15', 'lesson-audio-itops-b1-07', 'owner', 106, 114.4, 'Next, let us turn on two factor authentication on your phone so a stolen password alone cannot log in.', '[Security Ops] Tiếp theo hãy bật xác thực hai yếu tố trên điện thoại để riêng mật khẩu bị lộ không thể đăng nhập.', 'two factor authentication, stolen password', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-16', 'lesson-audio-itops-b1-07', 'owner', 114.4, 121.5, 'I just scanned the setup code in my authenticator app and entered the six digit code.', '[Staff] Tôi vừa quét mã cài đặt trong ứng dụng xác thực và nhập mã sáu chữ số rồi.', 'authenticator app, six digit code', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-17', 'lesson-audio-itops-b1-07', 'owner', 121.5, 129.9, 'Your account is secure again, and I have already blocked the sender and removed the email from other inboxes.', '[Security Ops] Tài khoản của bạn đã an toàn trở lại, và tôi đã chặn người gửi cũng như gỡ thư đó khỏi hộp thư người khác.', 'blocked the sender, removed', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-07-seg-18', 'lesson-audio-itops-b1-07', 'owner', 129.9, 137.4, 'Thanks so much for your patience; I will always check the sender address carefully from now on.', '[Staff] Cảm ơn bạn rất nhiều vì sự kiên nhẫn; từ giờ tôi sẽ luôn kiểm tra kỹ địa chỉ người gửi.', 'patience, carefully', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-08', 'owner', 'audio-itops-b1-08', 'B1 | 08. Fixing Broken Scheduled Backups & Storage Alerts (IT Ops)', 'A 2-minute B1 operations call investigating three failed overnight backup jobs, expired cloud storage permissions, manual recovery, and restore verification (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-1', 'lesson-audio-itops-b1-08', 'owner', 0, 8.4, 'Morning Liam, I noticed on the daily report that our file server backup failed three nights in a row.', '[Shift Operator] Chào buổi sáng Liam, mình thấy trên báo cáo hằng ngày là bản sao lưu máy chủ tệp lỗi ba đêm liên tiếp rồi.', 'daily report, three nights in a row', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-2', 'lesson-audio-itops-b1-08', 'owner', 8.4, 15.9, 'Three nights? Why did the monitoring board only show a yellow warning instead of a red alert?', '[Backup Eng] Ba đêm cơ à? Sao bảng giám sát chỉ hiện cảnh báo vàng thay vì cảnh báo đỏ vậy?', 'monitoring board, instead of', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-3', 'lesson-audio-itops-b1-08', 'owner', 15.9, 23.9, 'The alert rule only turns red after five failures, which feels far too late for important business files.', '[Shift Operator] Quy tắc cảnh báo chỉ chuyển đỏ sau năm lần lỗi, như vậy quá trễ đối với dữ liệu doanh nghiệp quan trọng.', 'far too late, business files', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-4', 'lesson-audio-itops-b1-08', 'owner', 23.9, 31.9, 'You are completely right; let us fix the broken backup first and tighten that alert rule immediately after.', '[Backup Eng] Cậu nói hoàn toàn đúng; trước hết hãy sửa bản sao lưu hỏng rồi siết chặt quy tắc cảnh báo ngay sau đó.', 'tighten, alert rule', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-5', 'lesson-audio-itops-b1-08', 'owner', 31.9, 40.3, 'I opened last night’s backup log, and the job failed right at the start with an access denied message.', '[Shift Operator] Mình mở nhật ký sao lưu đêm qua, tác vụ lỗi ngay từ đầu với thông báo bị từ chối truy cập.', 'access denied', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-6', 'lesson-audio-itops-b1-08', 'owner', 40.3, 46.6, 'Access denied usually means our cloud storage key expired or someone changed folder permissions.', '[Backup Eng] Từ chối truy cập thường có nghĩa khóa lưu trữ đám mây đã hết hạn hoặc có ai đổi quyền thư mục.', 'cloud storage key, permissions', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-7', 'lesson-audio-itops-b1-08', 'owner', 46.6, 53.7, 'Let me check the service account page; yes, the backup access key expired on Monday evening.', '[Backup Eng] Để tôi xem trang tài khoản dịch vụ; đúng rồi, khóa truy cập sao lưu vừa hết hạn tối thứ Hai.', 'service account, access key', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-8', 'lesson-audio-itops-b1-08', 'owner', 53.7, 60.8, 'Are all our local snapshots from the past week still safe on the office storage server?', '[Shift Operator] Toàn bộ bản chụp nội bộ tuần qua vẫn an toàn trên máy chủ lưu trữ văn phòng chứ?', 'local snapshots, storage server', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-9', 'lesson-audio-itops-b1-08', 'owner', 60.8, 67.9, 'Yes, local snapshots worked fine; only the offsite cloud upload failed because of the expired key.', '[Backup Eng] Có, bản chụp nội bộ vẫn chạy tốt; chỉ bước tải lên đám mây ngoài site bị lỗi do khóa hết hạn.', 'offsite cloud upload', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-10', 'lesson-audio-itops-b1-08', 'owner', 67.9, 75.4, 'I am creating a new service key now and updating the encrypted secret inside our backup tool.', '[Backup Eng] Tôi đang tạo khóa dịch vụ mới và cập nhật bí mật mã hóa bên trong công cụ sao lưu.', 'encrypted secret, backup tool', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-11', 'lesson-audio-itops-b1-08', 'owner', 75.4, 82.9, 'Should we wait until midnight to see if it works, or run a manual backup right now?', '[Shift Operator] Ta có nên đợi tới nửa đêm xem có chạy không, hay chạy sao lưu thủ công ngay bây giờ?', 'manual backup', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-12', 'lesson-audio-itops-b1-08', 'owner', 82.9, 89.6, 'Never wait until midnight after three failures; let us start an incremental upload right away.', '[Backup Eng] Đừng bao giờ đợi tới nửa đêm sau ba lần lỗi; hãy chạy tải lên gia tăng ngay lập tức.', 'incremental upload', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-13', 'lesson-audio-itops-b1-08', 'owner', 89.6, 95.5, 'The upload started cleanly and is transferring files at forty megabytes per second.', '[Shift Operator] Quá trình tải lên đã chạy gọn và đang truyền tệp ở tốc độ bốn mươi megabyte mỗi giây.', 'transferring files, per second', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-14', 'lesson-audio-itops-b1-08', 'owner', 95.5, 101.8, 'Since it is only an incremental sync, it should finish uploading within five minutes.', '[Backup Eng] Vì chỉ là đồng bộ gia tăng nên chắc sẽ tải xong trong vòng năm phút thôi.', 'incremental sync', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-15', 'lesson-audio-itops-b1-08', 'owner', 101.8, 109.8, 'It just finished with zero errors! Let us also restore one test folder to staging to be certain.', '[Shift Operator] Vừa chạy xong không một lỗi nào! Mình cũng khôi phục thử một thư mục mẫu lên staging cho chắc nhé.', 'to be certain, staging', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-16', 'lesson-audio-itops-b1-08', 'owner', 109.8, 114.8, 'The test restore succeeded and every document opened without any corruption.', '[Backup Eng] Bản khôi phục thử thành công và mọi tài liệu đều mở được không bị hỏng.', 'succeeded, corruption', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-17', 'lesson-audio-itops-b1-08', 'owner', 114.8, 123.6, 'Now I am updating the alert policy so even a single missed backup sends a red ticket the next morning.', '[Backup Eng] Giờ tôi cập nhật chính sách cảnh báo để chỉ cần lỡ một lần sao lưu là gửi phiếu đỏ ngay sáng hôm sau.', 'alert policy, missed backup', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-08-seg-18', 'lesson-audio-itops-b1-08', 'owner', 123.6, 131.1, 'Thanks Liam, I will add a reminder to rotate the storage key before it expires next quarter.', '[Shift Operator] Cảm ơn Liam, mình sẽ thêm nhắc lịch xoay khóa lưu trữ trước khi hết hạn vào quý sau.', 'next quarter, rotate', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-09', 'owner', 'audio-itops-b1-09', 'B1 | 09. Troubleshooting Slow API Calls & Timeout Errors (IT Ops)', 'A 2-minute B1 incident call tracing mobile app timeouts through API gateway logs to a slow third-party payment provider and adding safe timeouts (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-1', 'lesson-audio-itops-b1-09', 'owner', 0, 7.1, 'Hi Noah, mobile app users are reporting loading spinners and timeout errors when paying for orders.', '[App Support] Chào Noah, người dùng ứng dụng di động đang báo vòng xoay tải mãi và lỗi quá thời gian khi thanh toán đơn hàng.', 'loading spinners, timeout errors', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-2', 'lesson-audio-itops-b1-09', 'owner', 7.1, 15.9, 'Let me open the API gateway dashboard; yes, the error rate on the payment endpoint just climbed to twelve percent.', '[SRE] Để tôi mở bảng điều khiển cổng API; đúng rồi, tỷ lệ lỗi trên điểm cuối thanh toán vừa tăng lên 12%.', 'API gateway, error rate, endpoint', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-3', 'lesson-audio-itops-b1-09', 'owner', 15.9, 22.2, 'Are other mobile features like browsing products or viewing order history still working fast?', '[SRE] Các tính năng di động khác như xem sản phẩm hay lịch sử đơn hàng vẫn chạy nhanh chứ?', 'order history, browsing products', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-4', 'lesson-audio-itops-b1-09', 'owner', 22.2, 29.3, 'Yes, everything else responds in under half a second; only the checkout payment call is hanging.', '[App Support] Có, mọi thứ khác phản hồi dưới nửa giây; chỉ đúng lời gọi thanh toán lúc đặt hàng bị treo.', 'responds, hanging', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-5', 'lesson-audio-itops-b1-09', 'owner', 29.3, 38.1, 'Let us inspect the request traces to see whether the delay is inside our own code or an external partner.', '[SRE] Hãy kiểm tra dấu vết yêu cầu xem độ trễ nằm trong mã của ta hay ở phía đối tác bên ngoài.', 'request traces, external partner', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-6', 'lesson-audio-itops-b1-09', 'owner', 38.1, 46.9, 'Look at the timing breakdown: our internal service finishes in twenty milliseconds, then waits thirty seconds for the bank API.', '[SRE] Nhìn bảng phân tách thời gian này: dịch vụ nội bộ của ta xử lý xong trong 20 mili giây, rồi chờ 30 giây cho API ngân hàng.', 'timing breakdown, internal service', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-7', 'lesson-audio-itops-b1-09', 'owner', 46.9, 53.6, 'Thirty seconds is way too long! Let me check the payment provider’s public status page.', '[App Support] Ba mươi giây là quá lâu rồi! Để tôi kiểm tra trang trạng thái công khai của nhà cung cấp thanh toán.', 'payment provider, public status page', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-8', 'lesson-audio-itops-b1-09', 'owner', 53.6, 59.9, 'They just posted an incident notice confirming degraded performance on their European payment gateway.', '[App Support] Họ vừa đăng thông báo sự cố xác nhận hiệu năng bị suy giảm trên cổng thanh toán châu Âu của họ.', 'incident notice, degraded performance', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-9', 'lesson-audio-itops-b1-09', 'owner', 59.9, 67.9, 'Because our timeout was set to thirty seconds, waiting calls are tying up all our payment worker threads.', '[SRE] Vì thời gian chờ của ta đặt tới ba mươi giây, các cuộc gọi đang chờ đã chiếm hết luồng xử lý thanh toán.', 'tying up, worker threads', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-10', 'lesson-audio-itops-b1-09', 'owner', 67.9, 75.4, 'Can we lower the outgoing timeout to six seconds and show a polite retry message to users?', '[App Support] Ta có thể hạ thời gian chờ xuống sáu giây và hiện thông báo mời người dùng thử lại lịch sự không?', 'lower the timeout, retry message', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-11', 'lesson-audio-itops-b1-09', 'owner', 75.4, 81.3, 'Even better, we also have a secondary payment processor configured for backup routing.', '[SRE] Tốt hơn nữa, ta còn cấu hình sẵn một nhà cung cấp thanh toán dự phòng để chuyển hướng.', 'secondary processor, backup routing', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-12', 'lesson-audio-itops-b1-09', 'owner', 81.3, 89.3, 'Let us shift fifty percent of checkout traffic to the backup processor first and watch the success rate.', '[SRE] Hãy chuyển trước 50% lưu lượng thanh toán sang nhà cung cấp dự phòng rồi theo dõi tỷ lệ thành công.', 'shift traffic, success rate', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-13', 'lesson-audio-itops-b1-09', 'owner', 89.3, 96, 'Transactions on the backup gateway are succeeding in less than one second with zero timeouts.', '[App Support] Các giao dịch qua cổng dự phòng đang thành công dưới một giây và không có lỗi quá thời gian nào.', 'transactions, succeeding', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-14', 'lesson-audio-itops-b1-09', 'owner', 96, 103.1, 'Great, I am moving one hundred percent of payment traffic over until the primary partner recovers.', '[SRE] Tuyệt, tôi chuyển toàn bộ 100% lưu lượng thanh toán sang cho tới khi đối tác chính phục hồi.', 'primary partner, recovers', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-15', 'lesson-audio-itops-b1-09', 'owner', 103.1, 110.6, 'I also lowered the gateway timeout to eight seconds and added a safe limit on automatic retries.', '[SRE] Tôi cũng đã hạ thời gian chờ của cổng xuống tám giây và thêm giới hạn an toàn cho các lần thử lại tự động.', 'automatic retries', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-16', 'lesson-audio-itops-b1-09', 'owner', 110.6, 117.3, 'Support tickets already stopped coming in, and checkout conversion is back to its normal level.', '[App Support] Phiếu hỗ trợ đã ngừng đổ về rồi, và tỷ lệ hoàn tất thanh toán đã quay về mức bình thường.', 'checkout conversion, normal level', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-17', 'lesson-audio-itops-b1-09', 'owner', 117.3, 124.4, 'Let us keep an eye on the vendor status page before switching traffic back tomorrow morning.', '[SRE] Hãy theo dõi trang trạng thái của đối tác trước khi chuyển lưu lượng quay lại vào sáng mai.', 'keep an eye on, vendor', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-09-seg-18', 'lesson-audio-itops-b1-09', 'owner', 124.4, 129.4, 'Agreed; having a tested backup gateway really saved our afternoon today.', '[App Support] Nhất trí; có sẵn cổng dự phòng đã được kiểm thử thực sự cứu nguy cho buổi chiều hôm nay.', 'saved our afternoon', 17);

INSERT OR IGNORE INTO lessons (id, user_id, video_id, title, description, language, level) VALUES ('lesson-audio-itops-b1-10', 'owner', 'audio-itops-b1-10', 'B1 | 10. Running a Weekly Incident Review & Runbook Update (IT Ops)', 'A 2-minute B1 team operations meeting reviewing weekly incidents, reducing noisy alerts, improving step-by-step runbooks, and mentoring new engineers (~2 min, B1, UK English).', 'en', 'Intermediate');
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-1', 'lesson-audio-itops-b1-10', 'owner', 0, 8, 'Welcome to our Friday operations review; let us look calmly at the two incidents we handled this week.', '[Ops Manager] Chào mừng đến buổi rà soát vận hành thứ Sáu; cùng xem lại bình tĩnh hai sự cố ta xử lý tuần này nhé.', 'operations review, handled', 0);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-2', 'lesson-audio-itops-b1-10', 'owner', 8, 14.7, 'Overall uptime stayed above ninety nine percent, though Tuesday’s night alert took longer than expected.', '[SysAdmin] Thời gian hoạt động chung vẫn trên 99%, nhưng cảnh báo đêm thứ Ba mất thời gian xử lý lâu hơn dự kiến.', 'overall uptime, longer than expected', 1);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-3', 'lesson-audio-itops-b1-10', 'owner', 14.7, 21, 'What slowed the response down on Tuesday when the queue server stopped processing jobs?', '[Ops Manager] Điều gì đã làm chậm phản hồi vào thứ Ba khi máy chủ hàng đợi ngừng xử lý tác vụ?', 'slowed down, processing jobs', 2);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-4', 'lesson-audio-itops-b1-10', 'owner', 21, 29.4, 'First, our monitoring chat received nearly forty minor warnings that night, so the real problem was easy to miss.', '[SysAdmin] Thứ nhất, nhóm chat giám sát nhận gần bốn mươi cảnh báo nhỏ đêm đó nên rất dễ bỏ sót sự cố thật.', 'minor warnings, easy to miss', 3);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-5', 'lesson-audio-itops-b1-10', 'owner', 29.4, 35.7, 'Second, the restart instructions in our wiki were outdated after last month’s server upgrade.', '[SysAdmin] Thứ hai, hướng dẫn khởi động lại trên wiki đã cũ sau đợt nâng cấp máy chủ tháng trước.', 'instructions, outdated, upgrade', 4);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-6', 'lesson-audio-itops-b1-10', 'owner', 35.7, 43.7, 'That is very clear feedback; noisy alerts tire out the on call team and slow down real fixes.', '[Ops Manager] Phản hồi rất rõ ràng; cảnh báo ồn ào làm đội trực mệt mỏi và làm chậm việc sửa lỗi thật.', 'noisy alerts, tire out', 5);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-7', 'lesson-audio-itops-b1-10', 'owner', 43.7, 51.2, 'Which of those forty minor warnings can we safely silence or turn into a daily summary email?', '[Ops Manager] Trong bốn mươi cảnh báo nhỏ đó, loại nào ta có thể tắt an toàn hoặc gom thành email tổng hợp hằng ngày?', 'safely silence, daily summary', 6);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-8', 'lesson-audio-itops-b1-10', 'owner', 51.2, 59.2, 'Short CPU spikes that last under thirty seconds never require waking someone up at three in the morning.', '[SysAdmin] Các đợt tăng CPU ngắn dưới ba mươi giây không bao giờ cần đánh thức ai đó lúc ba giờ sáng.', 'CPU spikes, waking someone up', 7);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-9', 'lesson-audio-itops-b1-10', 'owner', 59.2, 66.7, 'Agreed; let us require high CPU to stay above eighty five percent for five minutes before paging.', '[Ops Manager] Nhất trí; hãy yêu cầu CPU cao duy trì trên 85% suốt năm phút mới gọi trực.', 'require, before paging', 8);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-10', 'lesson-audio-itops-b1-10', 'owner', 66.7, 73.4, 'What about updating our incident runbooks so new shift engineers can follow them with confidence?', '[Ops Manager] Còn việc cập nhật sổ tay sự cố để các kỹ sư ca mới làm theo thật tự tin thì sao?', 'shift engineers, with confidence', 9);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-11', 'lesson-audio-itops-b1-10', 'owner', 73.4, 80.5, 'I already rewrote the queue server runbook with exact commands, expected outputs, and clear rollback steps.', '[SysAdmin] Tôi đã viết lại sổ tay máy chủ hàng đợi với câu lệnh chính xác, kết quả mong đợi và bước hoàn tác rõ ràng.', 'exact commands, expected outputs', 10);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-12', 'lesson-audio-itops-b1-10', 'owner', 80.5, 87.6, 'Can we ask one of our newer engineers to test that runbook on staging next Tuesday?', '[Ops Manager] Ta có thể nhờ một kỹ sư mới chạy thử sổ tay đó trên môi trường staging thứ Ba tới không?', 'newer engineers, test on staging', 11);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-13', 'lesson-audio-itops-b1-10', 'owner', 87.6, 96, 'Great idea; if a new team member can follow every step smoothly, we know the document is truly clear.', '[SysAdmin] Ý tuyệt vời; nếu thành viên mới làm theo trôi chảy từng bước thì ta biết tài liệu thực sự rõ ràng.', 'truly clear, follow every step', 12);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-14', 'lesson-audio-itops-b1-10', 'owner', 96, 101.9, 'Let us also link each monitoring alert directly to its matching runbook page.', '[Ops Manager] Hãy gắn luôn đường dẫn trực tiếp từ mỗi cảnh báo giám sát tới trang sổ tay tương ứng.', 'link directly, matching runbook', 13);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-15', 'lesson-audio-itops-b1-10', 'owner', 101.9, 109.4, 'That saves precious minutes during an urgent phone call because nobody has to search through old folders.', '[SysAdmin] Việc đó tiết kiệm những phút quý giá trong cuộc gọi khẩn cấp vì không ai phải lục tìm thư mục cũ.', 'precious minutes, urgent phone call', 14);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-16', 'lesson-audio-itops-b1-10', 'owner', 109.4, 116.5, 'Before we wrap up, is there any upcoming maintenance or risky release planned for next week?', '[Ops Manager] Trước khi kết thúc, tuần tới có lịch bảo trì hay bản phát hành rủi ro nào không?', 'wrap up, upcoming maintenance', 15);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-17', 'lesson-audio-itops-b1-10', 'owner', 116.5, 122.8, 'Only a routine security patch on Wednesday evening, and backups are already verified ready.', '[SysAdmin] Chỉ có một đợt vá bảo mật định kỳ tối thứ Tư, và các bản sao lưu đều đã kiểm tra sẵn sàng.', 'routine security patch, verified', 16);
INSERT OR IGNORE INTO transcript_segments (id, lesson_id, user_id, start_time, end_time, text, translation, hint, sequence_order) VALUES ('audio-itops-b1-10-seg-18', 'lesson-audio-itops-b1-10', 'owner', 122.8, 129.5, 'Brilliant work everyone; fewer noisy alerts and clearer runbooks will make next week much calmer.', '[Ops Manager] Cả đội làm rất tốt; ít cảnh báo nhiễu hơn và sổ tay rõ hơn sẽ giúp tuần tới nhẹ nhàng hơn nhiều.', 'much calmer', 17);
